/// "Can I trust these numbers?": the numbers from app/assets/data/validation.json
/// (generated by the pipeline) and every modelling assumption/limitation.
library;

import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter/services.dart' show rootBundle;

import '../theme.dart';
import 'how_calculated.dart';

class ValidationPage extends StatelessWidget {
  const ValidationPage({super.key});

  static Future<Map<String, dynamic>> _load() async =>
      jsonDecode(await rootBundle.loadString('assets/data/validation.json')) as Map<String, dynamic>;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      // the title shrinks to fit narrow bars and large text instead of being cut
      appBar: AppBar(
        title: const FittedBox(
          fit: BoxFit.scaleDown,
          alignment: Alignment.centerLeft,
          child: Text('Validation & assumptions'),
        ),
      ),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _load(),
        builder: (context, snap) {
          if (snap.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Text('Could not load the validation report: ${snap.error}', style: PHText.body.copyWith(color: PH.muted)),
              ),
            );
          }
          if (!snap.hasData) return const Center(child: BusyIndicator(size: 36, strokeWidth: 4));
          final v = snap.data!;
          String am(num? x, [int d = 5]) => x == null ? '–' : '${x.toStringAsFixed(d)}′';
          Map<String, dynamic> m(String k) => (v[k] as Map?)?.cast<String, dynamic>() ?? const {};
          final hz = m('horizons'), app = m('app_vs_horizons'), spice = m('app_vs_spice'), de = m('de440_vs_de442');
          final fr = m('frame_sensitivity'), dip = m('horizon_dip'), avg = m('avgvis'), sky = m('render_skyline');
          Map<String, dynamic> b(Map<String, dynamic> x, String k) => (x[k] as Map?)?.cast<String, dynamic>() ?? const {};
          return LayoutBuilder(builder: (context, box) {
            // one readable column, centred on wide screens
            final side = math.max(16.0, (box.maxWidth - 840) / 2);
            return ListView(padding: EdgeInsets.fromLTRB(side, 12, side, 32), children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(4, 8, 4, 8),
                child: Semantics(header: true, child: const Text('Can I trust these numbers?', style: PHText.headline)),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(4, 0, 4, 16),
                child: Text(
                    'Each step of the calculation is checked against an independent source. Below are the checks, what '
                    'the app assumes, and what it leaves out.',
                    style: PHText.body.copyWith(color: PH.muted)),
              ),
              _section('In short', null, [
                _Row('Sun and Earth directions vs NASA JPL Horizons (worst case)',
                    _worst(b(app, 'sun')['maxArcmin'], b(app, 'earth')['maxArcmin']),
                    'arcminutes; the Sun\'s disk is about 32 arcminutes wide'),
                if (b(avg, 'regions').isNotEmpty)
                  _Row('Long-term sunlit time vs the NASA LOLA team\'s maps',
                      '${b(avg, 'regions')['meanAbsDiffSunPct'] ?? '–'} points',
                      'average difference for the landing regions, over 18.6 years',
                      share: true),
                if (sky.isNotEmpty)
                  _Row('Skylines vs an independent ray tracer',
                      'mean ${(b(sky, 'overall')['meanOfMeansAbsDeg'] as num?)?.toStringAsFixed(2) ?? '–'}°',
                      '${(sky['sites'] as Map?)?.length ?? '–'} preset sites'),
                const Padding(
                  padding: EdgeInsets.only(top: 4),
                  child: FidelityBadge(text: FidelityBadge.customHorizon),
                ),
                Padding(
                  padding: const EdgeInsets.only(top: 12),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: FilledButton.tonal(
                      onPressed: () => Navigator.of(context)
                          .push(MaterialPageRoute<void>(builder: (_) => const HowCalculatedPage())),
                      child: const Text('How it\'s calculated'),
                    ),
                  ),
                ),
              ]),
              _section('Ephemeris and geometry', 'Errors on the sky, arcminutes; the Sun is ~32′ wide', [
                _Row('Pipeline (SPICE DE440, MOON_ME) vs JPL Horizons · Sun / Earth (max)',
                    '${am(b(hz, 'sun')['maxArcmin'])} / ${am(b(hz, 'earth')['maxArcmin'])}',
                    '${(b(hz, 'sun')['n'] ?? 0) + (b(hz, 'earth')['n'] ?? 0)} comparisons, 8 sites, 3 windows 2025–2035'),
                _Row('This app (shipped ephemeris + interpolation + parallax) vs Horizons · Sun / Earth (max)',
                    '${am(b(app, 'sun')['maxArcmin'])} / ${am(b(app, 'earth')['maxArcmin'])}', 'what you see on screen'),
                _Row('This app vs direct SPICE at 2000 random sites/times (max)',
                    '${am(b(spice, 'sun')['maxArcmin'])} / ${am(b(spice, 'earth')['maxArcmin'])}', 'Sun / Earth'),
                _Row('Same check with the WRONG lunar frame (shows the test is sensitive)',
                    'PA ${am(b(fr, 'MOON_PA')['maxArcmin'], 2)} · IAU ${am(b(fr, 'IAU_MOON')['maxArcmin'], 2)}',
                    'MOON_ME matches Horizons; MOON_PA / IAU_MOON would not'),
                _Row('DE440 vs DE442 planetary ephemeris (max)',
                    '${am(b(de, 'sun')['maxArcmin'], 7)} / ${am(b(de, 'earth')['maxArcmin'], 7)}', 'negligible'),
              ]),
              _section('Terrain horizons', null, [
                for (final c in ((dip['cases'] as List?) ?? const []).cast<Map>())
                  _Row('Smooth-sphere dip at ${c['observerHeightM']} m (ray-march vs exact)',
                      '${(c['errArcmin'] as num).toStringAsExponential(1)}′', 'analytic check of the horizon algorithm'),
                if (sky.isNotEmpty)
                  _Row('Skyline ray-traced in Blender from the LOLA terrain vs our horizon masks, 16 sites',
                      'mean ${(b(sky, 'overall')['meanOfMeansAbsDeg'] as num?)?.toStringAsFixed(3) ?? '–'}° · worst '
                          '${(b(sky, 'overall')['worstMaxAbsDeg'] as num?)?.toStringAsFixed(3) ?? '–'}°',
                      'a one-off check with an independent renderer (the app no longer shows these images); '
                          '~1–2 px at 0.088°/px'),
              ]),
              _section('End-to-end illumination vs NASA LOLA team maps', 'Mazarico et al. 2011 method, 18.6-year average', [
                _Row('Region-type sites: mean |Δ| sunlit / Earth-visible',
                    '${b(avg, 'regions')['meanAbsDiffSunPct'] ?? '–'}% / ${b(avg, 'regions')['meanAbsDiffEarthPct'] ?? '–'}%',
                    'values inside LOLA\'s own 3×3-pixel range: ${b(avg, 'regions')['valuesWithinLola3x3'] ?? '–'}',
                    share: true),
                _Row('Sharp ridge/peak points: mean |Δ| sunlit / Earth',
                    '${b(avg, 'ridgePeakPoints')['meanAbsDiffSunPct'] ?? '–'}% / ${b(avg, 'ridgePeakPoints')['meanAbsDiffEarthPct'] ?? '–'}%',
                    'sub-pixel terrain dominates; inside LOLA 3×3: ${b(avg, 'ridgePeakPoints')['valuesWithinLola3x3'] ?? '–'}',
                    share: true),
                Padding(
                  padding: const EdgeInsets.only(top: 10),
                  child: Text((avg['interpretation'] ?? '') as String, style: PHText.small.copyWith(color: PH.muted)),
                ),
              ]),
              _section('Assumptions', null, const [
                _Bullet('Ephemeris: NASA/JPL SPICE, DE440 planets + DE440 lunar libration; body frame MOON_ME (= LOLA\'s DE421 mean-Earth frame, < 1 m).'),
                _Bullet('Apparent directions (light time + stellar aberration), matching JPL Horizons "airless apparent" az/el. No refraction (no atmosphere).'),
                _Bullet('Times are UTC; no leap seconds after 2016 are assumed. Data span 2025-01-01 00:00 to 2035-12-31 23:00 UTC (the last hourly sample), interpolated between hours; a period ending on 31 Dec 2035 stops at that last sample.'),
                _Bullet('Moon = 1737.4 km sphere + LOLA heights. Observer 2 m (lander) or 10 m (mast) above the terrain. Azimuth from local north (away from the pole), clockwise.'),
                _Bullet('Default rules: the Sun is up when any part of its disk is above the terrain (LOLA convention); Earth is in view when Earth\'s centre is above it. The rules, the DSN check, the period and the lander or mast height are all set in Mission settings (the pill at the top of the app).'),
                _Bullet('Power proxy = 1361 W/m² × (1 au/r)² × visible fraction of the Sun\'s disk, for a panel facing the Sun.'),
                _Bullet('Optional DSN check: Moon centre ≥ 10° above the horizon at Goldstone, Madrid or Canberra (ITRF93 Earth orientation). It is stored hourly and not interpolated: each 10- or 30-minute step uses the nearest stored hour, so station rise and set times are accurate to about ±30 minutes.'),
              ]),
              _section('Limitations', null, const [
                _Bullet('Preset horizons come from the LOLA 80 m DEM (240 m beyond 80°S). Terrain within 120 m is not resolved and is ignored; boulders and local slopes need higher-resolution data.'),
                _Bullet('Custom sites use a 400 m DEM (to about 75°S) computed on the device: typically 0.5–1.4° horizon error (up to ~6° on sharp rims). Use them to explore, not to decide.'),
                _Bullet('Artemis III presets are approximate centres of ~15×15 km regions (LROC/Henriksen et al. 2023), not official landing points. Slater Plain is omitted: no published centre.'),
                _Bullet('Earth visibility does not include lunar-surface multipath, antenna masks or link budgets.'),
                _Bullet('The Explore map\'s base layer is shaded relief computed from LOLA elevations (320 m per pixel) with an artificial light from the upper left and heights exaggerated ×2. It shows the shape of the terrain, not a photo and not real lighting. Where a Light & shadow close-up reaches past the base map\'s edge (about 80°S), the same shading is computed on the device from the 400 m terrain grid (LOLA LDEM_75S_120M there).'),
                _Bullet('The light & shadow map is computed on the device from the 400 m (or 800 m) LOLA elevation map. Its "sunlit or not" agrees with the per-site horizon calculations 82–94% of the time (by map resolution and horizon source), so it can differ near shadow edges.'),
              ]),
              Padding(
                padding: const EdgeInsets.fromLTRB(4, 8, 4, 0),
                child: Text('Report generated ${v['generatedUtc'] ?? ''}. Full details: the README, formula.md and the pipeline tests.',
                    style: PHText.small.copyWith(color: PH.muted)),
              ),
            ]);
          });
        },
      ),
    );
  }

  /// The larger of two arcminute errors, e.g. "0.0016′".
  static String _worst(Object? a, Object? b) {
    final xs = [a, b].whereType<num>().toList();
    if (xs.isEmpty) return '–';
    return '${xs.reduce(math.max).toStringAsFixed(4)}′';
  }

  static Widget _section(String title, String? note, List<Widget> children) => Card(
        margin: const EdgeInsets.only(bottom: 12),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 18, 20, 18),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Text(title, style: PHText.subtitle),
            if (note != null) Text(note, style: PHText.small.copyWith(color: PH.muted)),
            const SizedBox(height: 8),
            ...children,
          ]),
        ),
      );
}

/// One check: what was compared, the result, and a note. The result sits on
/// the right on wide screens and under the text on phones.
class _Row extends StatelessWidget {
  final String what, value, note;

  /// Percentages (statStyle); otherwise exact angles (numStyle).
  final bool share;
  const _Row(this.what, this.value, this.note, {this.share = false});

  @override
  Widget build(BuildContext context) {
    final valueStyle = share ? statStyle(size: 16) : numStyle(size: 14, weight: FontWeight.w600);
    final text = Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(what, style: PHText.body),
      Text(note, style: PHText.small.copyWith(color: PH.muted)),
    ]);
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: LayoutBuilder(builder: (context, c) {
        if (c.maxWidth < 520) {
          return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            text,
            const SizedBox(height: 4),
            Text(value, style: valueStyle),
          ]);
        }
        return Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Expanded(flex: 5, child: text),
          const SizedBox(width: 16),
          Expanded(flex: 3, child: Text(value, textAlign: TextAlign.right, style: valueStyle)),
        ]);
      }),
    );
  }
}

class _Bullet extends StatelessWidget {
  final String text;
  const _Bullet(this.text);
  @override
  Widget build(BuildContext context) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Padding(
            padding: const EdgeInsets.only(top: 9, right: 12, left: 2),
            child: Container(width: 5, height: 5, decoration: const BoxDecoration(color: PH.muted, shape: BoxShape.circle)),
          ),
          Expanded(child: Text(text, style: PHText.body)),
        ]),
      );
}
